// MP-121: the promoted skill copies under .mergeproof/skills/ are generated by
// scripts/promote.mjs from skills/ and must never drift ahead of what ships.
// The copy may lag (promote has not run since a skill was bumped) but it may
// never be newer, never differ at the same version, and never name a skill the
// package does not ship. Windows checkouts (core.autocrlf) put CRLF in the
// working tree, so content is compared LF-normalized.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdirSync, mkdtempSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';

const skill = (version, body = 'The playbook body.\n') =>
  `---\nname: mergeproof-x\nversion: ${version}\ndescription: A playbook for the gate's agent.\n---\n\n# mergeproof-x\n\n${body}`;

/** { version, content } of a SKILL.md, with the version asserted to be an integer and CRLF normalized. */
function readSkill(dir, name) {
  const file = join(dir, name, 'SKILL.md');
  const text = readFileSync(file, 'utf8');
  const fm = /^---\r?\n([\s\S]*?)\r?\n---/.exec(text);
  assert.ok(fm, `${file} must start with YAML frontmatter`);
  const line = fm[1].split(/\r?\n/).find((l) => l.startsWith('version:'));
  const version = line == null ? null : Number(line.slice('version:'.length).trim());
  assert.ok(Number.isInteger(version), `${file} needs an integer version`);
  return { version, content: text.replace(/\r\n/g, '\n') };
}

/**
 * The promotion invariants for a shipped skills directory and its promoted
 * copy: no orphan skills, a copy never newer than what ships, and equal
 * versions byte-identical (modulo line endings). Throws on the first breach.
 */
function checkSkillCopies(shippedDir, promotedDir) {
  const shipped = new Set(
    readdirSync(shippedDir, { withFileTypes: true })
      .filter((e) => e.isDirectory())
      .map((e) => e.name),
  );
  assert.ok(shipped.size > 0, `${shippedDir} must ship at least one skill`);
  const promoted = readdirSync(promotedDir, { withFileTypes: true }).filter((e) => e.isDirectory()).map((e) => e.name);
  for (const name of promoted) {
    assert.ok(shipped.has(name), `.mergeproof/skills/${name} is not shipped under skills/ (orphan promoted copy; re-run scripts/promote.mjs)`);
    const ship = readSkill(shippedDir, name);
    const copy = readSkill(promotedDir, name);
    assert.ok(copy.version <= ship.version, `promoted skills/${name} is version ${copy.version}, newer than the shipped ${ship.version}; only scripts/promote.mjs may update the copy`);
    if (copy.version === ship.version) {
      assert.equal(copy.content, ship.content, `promoted skills/${name} is version ${ship.version} like the shipped one, but the content differs`);
    }
  }
}

test('this repo\'s promoted skill copies satisfy the promotion invariants', () => {
  checkSkillCopies(resolve('skills'), resolve('.mergeproof/skills'));
});

test('checkSkillCopies accepts a lagging copy and an identical one, across line endings', async (t) => {
  const dir = mkdtempSync(join(tmpdir(), 'mp-skills-'));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  const shipped = join(dir, 'skills');
  const promoted = join(dir, 'promoted');
  mkdirSync(join(shipped, 'alpha'), { recursive: true });
  mkdirSync(join(shipped, 'beta'), { recursive: true });
  mkdirSync(join(promoted, 'alpha'), { recursive: true });
  mkdirSync(join(promoted, 'beta'), { recursive: true });
  writeFileSync(join(shipped, 'alpha', 'SKILL.md'), skill(3, 'Third edition.\n'));
  writeFileSync(join(shipped, 'beta', 'SKILL.md'), skill(2, 'Second edition.\n'));
  // alpha: an older copy is fine (promote has not run since the bump).
  writeFileSync(join(promoted, 'alpha', 'SKILL.md'), skill(2, 'Second edition.\n'));
  // beta: same version, same bytes — but CRLF, as a Windows checkout of the copy would be.
  writeFileSync(join(promoted, 'beta', 'SKILL.md'), skill(2, 'Second edition.\n').replace(/\n/g, '\r\n'));
  checkSkillCopies(shipped, promoted);
});

test('checkSkillCopies fails when the promoted copy is newer than the shipped skill', async (t) => {
  const dir = mkdtempSync(join(tmpdir(), 'mp-skills-'));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  const shipped = join(dir, 'skills');
  const promoted = join(dir, 'promoted');
  mkdirSync(join(shipped, 'alpha'), { recursive: true });
  mkdirSync(join(promoted, 'alpha'), { recursive: true });
  writeFileSync(join(shipped, 'alpha', 'SKILL.md'), skill(2));
  writeFileSync(join(promoted, 'alpha', 'SKILL.md'), skill(3, 'Hand-edited copy.\n'));
  assert.throws(() => checkSkillCopies(shipped, promoted), /newer than the shipped 2/);
});

test('checkSkillCopies fails when the versions are equal but the content differs', async (t) => {
  const dir = mkdtempSync(join(tmpdir(), 'mp-skills-'));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  const shipped = join(dir, 'skills');
  const promoted = join(dir, 'promoted');
  mkdirSync(join(shipped, 'alpha'), { recursive: true });
  mkdirSync(join(promoted, 'alpha'), { recursive: true });
  writeFileSync(join(shipped, 'alpha', 'SKILL.md'), skill(2, 'Shipped body.\n'));
  writeFileSync(join(promoted, 'alpha', 'SKILL.md'), skill(2, 'A body someone edited by hand.\n'));
  assert.throws(() => checkSkillCopies(shipped, promoted), /version 2 like the shipped one, but the content differs/);
});

test('checkSkillCopies fails on an orphan promoted skill with no shipped original', async (t) => {
  const dir = mkdtempSync(join(tmpdir(), 'mp-skills-'));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  const shipped = join(dir, 'skills');
  const promoted = join(dir, 'promoted');
  mkdirSync(join(shipped, 'alpha'), { recursive: true });
  mkdirSync(join(promoted, 'alpha'), { recursive: true });
  mkdirSync(join(promoted, 'removed-long-ago'), { recursive: true });
  writeFileSync(join(shipped, 'alpha', 'SKILL.md'), skill(2));
  writeFileSync(join(promoted, 'alpha', 'SKILL.md'), skill(2));
  writeFileSync(join(promoted, 'removed-long-ago', 'SKILL.md'), skill(1, 'A skill nobody ships.\n'));
  assert.throws(() => checkSkillCopies(shipped, promoted), /removed-long-ago.*orphan promoted copy/);
});
